const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>n===null?'—':n.toLocaleString('pt-BR',{style:'currency',currency:'BRL'}),num=n=>n.toLocaleString('pt-BR');
let rows=[];try{rows=JSON.parse(localStorage.getItem('beco-sales-v1')||'[]')}catch{}let page='overview',pending=null;
const titles={overview:['Clareza para crescer.','Entenda suas vendas. Encontre oportunidades. Faça o cliente voltar.'],menu:['Cada sabor tem seu papel.','Compare o giro, a receita e a contribuição de cada item.'],retention:['Uma colherada. Muitas voltas.','Acompanhe quem compra de novo e encontre espaço para reconquistar.'],insights:['O próximo passo, mais claro.','Sinais calculados a partir dos seus dados. Hipóteses para testar com critério.'],research:['Olhar para fora. Decidir melhor.','Gelato saudável • mercado, tendências e testes para o Beco Gelato.'],data:['Dados reais. Decisões reais.','Importe suas vendas para transformar este hub em uma rotina de gestão.']};
function populate(){let old=$('#item').value;$('#item').innerHTML='<option value="">Todos os itens</option>'+[...new Set(rows.map(r=>r.item))].sort().map(i=>`<option>${esc(i)}</option>`).join('');$('#item').value=old}
function range(){let a=$('#start').value,b=$('#end').value;if(!a||!b||a>b)throw Error('Escolha um período válido: a data inicial deve ser anterior ou igual à final.');let days=Math.round((Date.parse(b)-Date.parse(a))/864e5)+1;return {a,b,days,pa:new Date(Date.parse(a)-days*864e5).toISOString().slice(0,10),pb:new Date(Date.parse(a)-864e5).toISOString().slice(0,10)}}
function subset(a,b,item=$('#item').value){return rows.filter(r=>r.data>=a&&r.data<=b&&(!item||r.item===item))}
function stats(rs){let orders=new Set(rs.map(r=>r.pedido_id)),ids=new Map;rs.forEach(r=>{if(r.cliente_id){if(!ids.has(r.cliente_id))ids.set(r.cliente_id,new Set);ids.get(r.cliente_id).add(r.pedido_id)}});let repeat=[...ids.values()].filter(s=>s.size>=2).length;let rev=rs.reduce((s,r)=>s+r.receita_liquida,0);return {rev,orders:orders.size,units:rs.reduce((s,r)=>s+r.quantidade,0),ticket:orders.size?rev/orders.size:null,customers:ids.size,repeat,rate:ids.size?repeat/ids.size*100:null,cost:rs.length&&rs.every(r=>r.custo_total!==null)?rs.reduce((s,r)=>s+r.custo_total,0):null}}
function delta(a,b){return $('#compare').value==='none'?'Comparação desativada':b?`${((a-b)/b*100)>=0?'+':''}${((a-b)/b*100).toFixed(1)}% vs. período anterior`:'Sem base anterior para comparação'}
function kpi(label,value,sub){return `<div class="card"><label>${label}<span>↗</span></label><div class="value">${value}</div><small>${sub}</small></div>`}
function items(rs){return [...new Set(rs.map(r=>r.item))].map(item=>({item,...stats(rs.filter(r=>r.item===item))})).sort((a,b)=>b.rev-a.rev)}
function chart(rs,prev,r){if(!rs.length)return '<div class="chartempty"><div><div class="emptyicon">▥</div><strong>O próximo capítulo começa com seus dados.</strong><p>Importe as vendas para visualizar a evolução do negócio.</p></div></div>';let buckets=Math.min(r.days,30),ar=Array(buckets).fill(0),br=Array(buckets).fill(0);rs.forEach(v=>ar[Math.min(buckets-1,Math.floor((Date.parse(v.data)-Date.parse(r.a))/864e5/r.days*buckets))]+=v.receita_liquida);prev.forEach(v=>br[Math.min(buckets-1,Math.floor((Date.parse(v.data)-Date.parse(r.pa))/864e5/r.days*buckets))]+=v.receita_liquida);let max=Math.max(...ar,...br,1),path=v=>v.map((n,i)=>`${i?'L':'M'}${40+i*550/Math.max(1,buckets-1)},${195-n/max*155}`).join(' ');return `<div class="chart"><svg viewBox="0 0 630 235" role="img" aria-label="Evolução da receita atual e anterior"><text x="5" y="20" fill="#9aa28d" font-size="10">${money(max)}</text>${[40,90,140,195].map(y=>`<path d="M40 ${y} H600" stroke="#edf0e8"/>`).join('')}<path d="${path(ar)} L590 195 L40 195Z" fill="#eef2e6"/><path d="${path(ar)}" fill="none" stroke="#657b4f" stroke-width="3"/>${$('#compare').value==='previous'?`<path d="${path(br)}" fill="none" stroke="#b8bfb0" stroke-width="2" stroke-dasharray="5 5"/>`:''}<text x="40" y="224" font-size="10" fill="#8b9580">${r.a.split('-').reverse().join('/')}</text><text x="510" y="224" font-size="10" fill="#8b9580">${r.b.split('-').reverse().join('/')}</text></svg></div>`}
function signalCards(rs){let its=items(rs),total=stats(rs),low=its.filter(x=>x.units/total.units<.05),high=its.filter(x=>x.cost!==null&&x.rev>0&&x.cost/x.rev>.4);return `<div class="insightgrid"><div class="insight"><span class="symbol">↘</span><h3>Itens com baixo giro</h3><p>${rs.length?(low.length?low.map(x=>esc(x.item)).join(', '):'Nenhum item vendido abaixo do limite neste recorte.'):'Descubra quais sabores precisam de atenção.'}</p><small>Regra: menos de 5% das unidades do recorte.</small></div><div class="insight"><span class="symbol">◈</span><h3>Custos sob atenção</h3><p>${high.length?high.map(x=>esc(x.item)).join(', '):total.cost===null?'Importe custos para avaliar a contribuição por item.':'Nenhum item acima do limite de custo.'}</p><small>Regra: custo informado acima de 40% da receita.</small></div><div class="insight"><span class="symbol">↻</span><h3>Uma nova visita começa aqui</h3><p>${total.customers?`${total.customers-total.repeat} clientes identificados fizeram apenas um pedido no período.`:'Inclua IDs anônimos de clientes para medir recompra.'}</p><small>Oportunidade de testar uma ação de retorno.</small></div></div>`}
function render(){let r;try{r=range()}catch(e){$('#filtermsg').textContent=e.message;return}let rs=subset(r.a,r.b),prev=subset(r.pa,r.pb),s=stats(rs),p=stats(prev),its=items(rs);$('#title').textContent=titles[page][0];$('#subtitle').textContent=titles[page][1];$('#crumb').textContent=({overview:'Visão geral',menu:'Cardápio',retention:'Recorrência',insights:'Insights',research:'Pesquisa',data:'Central de dados'})[page];document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#filterbar').style.display=['data','research'].includes(page)?'none':'flex';$('#filtermsg').textContent=['data','research'].includes(page)?'':`${rs.length?num(rs.length)+' linhas no recorte':'Sem vendas importadas neste período'}${$('#compare').value==='previous'?' • Comparação: '+r.pa.split('-').reverse().join('/')+' a '+r.pb.split('-').reverse().join('/'):''}`;let html='';
if(page==='overview'){html=`${!rows.length?'<div class="banner"><span class="icon">↗</span><div><strong>Seu hub está pronto. Vamos conectar os números?</strong><p>Nenhum valor simulado. Importe um CSV para começar a enxergar oportunidades.</p></div><button data-page="data">Começar agora →</button></div>':''}<div class="cards">${kpi('Receita líquida',rs.length?money(s.rev):'—',rs.length?delta(s.rev,p.rev):'Aguardando dados de vendas')}${kpi('Pedidos',rs.length?num(s.orders):'—',rs.length?delta(s.orders,p.orders):'Aguardando dados de vendas')}${kpi('Ticket médio',money(s.ticket),rs.length?delta(s.ticket,p.ticket):'Receita ÷ pedidos únicos')}${kpi('Clientes recorrentes',s.rate===null?'—':s.rate.toFixed(1)+'%',s.customers?s.repeat+' de '+s.customers+' clientes identificados':'Aguardando identificação de clientes')}</div><div class="grid"><div class="panel"><div class="panelhead"><div><h2>O ritmo das vendas</h2><p>Receita líquida ao longo do período</p></div><span class="tag">${rs.length?'Dados importados':'Sem dados'}</span></div>${chart(rs,prev,r)}<div class="legend"><span>● Período selecionado</span><span>┄ Período anterior ${$('#compare').value==='none'?'(oculto)':''}</span></div></div><div class="panel"><div class="panelhead"><div><h2>Sabores em destaque</h2><p>Ranking por receita no período</p></div><span class="tag">Cardápio</span></div>${its.length?its.slice(0,4).map((x,i)=>`<div class="listrow"><span class="number">0${i+1}</span><div><strong>${esc(x.item)}</strong><p>${num(x.units)} unidades</p></div><span>${money(x.rev)}</span></div>`).join(''):[1,2,3,4].map(i=>`<div class="listrow"><span class="number">0${i}</span><div><strong>Próximo sabor em destaque</strong><p>Aguardando vendas importadas</p></div><span>—</span></div>`).join('')}</div></div><div class="sectionhead"><h2>Um olhar para as oportunidades</h2><span>Dados que viram ação</span></div>${signalCards(rs)}`}
if(page==='menu'){html=`<div class="panel"><div class="panelhead"><div><h2>Desempenho por item</h2><p>Receita líquida após descontos e taxas. Contribuição = receita líquida − custo informado.</p></div><span class="tag">${its.length} itens</span></div><div class="tablewrap"><table><thead><tr><th>ITEM</th><th>UNIDADES</th><th>RECEITA</th><th>VARIAÇÃO RECEITA</th><th>CUSTO</th><th>CONTRIBUIÇÃO</th></tr></thead><tbody>${its.length?its.map(x=>`<tr><td>${esc(x.item)}</td><td>${num(x.units)}</td><td>${money(x.rev)}</td><td>${delta(x.rev,stats(prev.filter(v=>v.item===x.item)).rev)}</td><td>${money(x.cost)}</td><td>${x.cost===null?'—':money(x.rev-x.cost)}</td></tr>`).join(''):'<tr><td colspan="6" class="emptycell">Importe suas vendas para revelar o desempenho de cada sabor.</td></tr>'}</tbody></table></div></div><div class="panel" style="margin-top:20px"><h2>Compare dois sabores</h2><p>Comparação no período selecionado, independente do filtro de item acima.</p><div class="compareitems"><select id="itemA" aria-label="Primeiro sabor">${items(subset(r.a,r.b,'')).map(x=>`<option>${esc(x.item)}</option>`).join('')}</select><select id="itemB" aria-label="Segundo sabor">${items(subset(r.a,r.b,'')).map(x=>`<option>${esc(x.item)}</option>`).join('')}</select></div><div id="itemresult"></div></div>`}
if(page==='retention'){let missing=rs.filter(v=>!v.cliente_id).length;html=`<div class="cards">${kpi('Clientes identificados',s.customers||'—','IDs distintos no período')}${kpi('Compraram novamente',s.customers?s.repeat:'—','2 ou mais pedidos no período')}${kpi('Taxa de recorrência',s.rate===null?'—':s.rate.toFixed(1)+'%','Recorrentes ÷ identificados')}${kpi('Cobertura de identificação',rs.length?((1-missing/rs.length)*100).toFixed(1)+'%':'—','Percentual de linhas com cliente')}</div><div class="panel" style="margin-top:24px"><h2>Frequência de compra</h2><p>A recompra é medida dentro do período filtrado. Não representa retenção de coorte nem primeira compra de toda a vida do cliente.</p><div class="tablewrap"><table><thead><tr><th>FREQUÊNCIA NO PERÍODO</th><th>CLIENTES</th><th>OPORTUNIDADE A TESTAR</th></tr></thead><tbody><tr><td>1 pedido</td><td>${s.customers?s.customers-s.repeat:'—'}</td><td>Um convite para conhecer outro sabor</td></tr><tr><td>2 ou mais pedidos</td><td>${s.customers?s.repeat:'—'}</td><td>Valorizar a frequência e testar kits</td></tr></tbody></table></div><div class="note"><p>Use um identificador anônimo e estável por cliente. Sem ele, a recorrência não pode ser medida. ${missing?missing+' linhas sem identificação foram excluídas deste cálculo.':''} Ao filtrar um item, a frequência considera apenas pedidos contendo esse item.</p></div></div>`}
if(page==='insights'){html=`${signalCards(rs)}<div class="panel" style="margin-top:24px"><h2>Transforme o sinal em um teste</h2><div class="listrow"><span class="number">01</span><div><strong>Giro baixo → revisar exposição antes de retirar</strong><p>Teste foto, descrição e posição no cardápio. Compare unidades e contribuição em períodos equivalentes.</p></div><span class="tag hyp">Hipótese</span></div><div class="listrow"><span class="number">02</span><div><strong>Custo alto → revisar ficha técnica e perdas</strong><p>O sinal de 40% é um limite exploratório, não prova desperdício. Custos fixos, estoque e perdas não estão nesta base.</p></div><span class="tag hyp">Hipótese</span></div><div class="listrow"><span class="number">03</span><div><strong>Uma compra → testar um convite de retorno</strong><p>Compare um grupo com oferta e outro sem oferta. Avalie contribuição incremental, além de pedidos.</p></div><span class="tag hyp">Hipótese</span></div><div class="note"><p>Os alertas refletem somente linhas importadas. Itens sem nenhuma venda não podem ser detectados sem um cadastro completo do cardápio; indisponibilidade e estoque não são conhecidos. Não retire produtos automaticamente com base neste painel.</p></div></div>`}
if(page==='research'){html=`<div class="researchhero"><span class="tag">O BECO GELATO • INTELIGÊNCIA DE MERCADO</span><h2>Sabor primeiro. Equilíbrio como diferencial.</h2><p>Pesquisa sobre gelatos e sorvetes com propostas de saudabilidade: proteína, menos açúcar, opções sem lactose, frutas e experiência premium. Fontes consultadas em 15/11/2026; atualização manual.</p></div><div class="researchcards"><div class="panel"><span class="tag fact">Dado setorial amplo</span><div class="big">R$ 14 bi+</div><h2>Setor brasileiro de sorvetes e gelatos</h2><p>A ABIS informa faturamento anual acima desse valor. O ano-base do indicador não está explícito na página; não é o tamanho do nicho saudável nem um dado específico de 2026.</p><a href="https://abis.com.br/mercado/" target="_blank" rel="noopener">ABIS · dados de mercado ↗</a></div><div class="panel"><span class="tag hyp">Sinal de tendência · 2026</span><div class="big">Proteína</div><h2>Funcionalidade com prazer</h2><p>A cobertura da Fispal Sorvetes 2026 destaca versões proteicas e zero açúcar. É um sinal de inovação da indústria, não um ranking de vendas ou prova de demanda local.</p><a href="https://www.foodconnection.com.br/sorvetes/sorvetes-e-confeitaria-tendencias-de-saudabilidade-e-premiumizacao/" target="_blank" rel="noopener">Redação Fispal · 17/08/2026 ↗</a></div><div class="panel"><span class="tag hyp">Análise setorial · 2025</span><div class="big">Inclusão</div><h2>Clareza sobre composição</h2><p>Artigo da ABIS aborda opções sem lactose, vegetais e com menos açúcar, com informação clara de ingredientes e alergênicos. Trata-se de análise qualitativa, sem participação de mercado por segmento.</p><a href="https://abis.com.br/inclusao-alimentar-nas-sorveterias-mais-que-tendencia-um-novo-posicionamento/" target="_blank" rel="noopener">ABIS · Maira Figueiredo · 05/06/2025 ↗</a></div></div><div class="panel" style="margin-top:22px"><h2>O que isso significa para as linhas do Beco</h2><p>Aplicações abaixo são hipóteses para testar. Não são conclusões das fontes sobre a marca.</p><div class="tablewrap"><table><thead><tr><th>FRENTE</th><th>SINAL EXTERNO</th><th>HIPÓTESE PARA O BECO</th><th>COMO VALIDAR</th></tr></thead><tbody><tr><td>Boost · proteicos</td><td>Proteína associada à experiência de sobremesa na Fispal 2026.</td><td>Testar comunicação que começa pelo sabor e apresenta proteína como complemento.</td><td>Comparar conversão, recompra e contribuição com a comunicação centrada no benefício funcional.</td></tr><tr><td>Special · sobremesas</td><td>Premiumização e experiências sensoriais destacadas na Fispal 2026.</td><td>Valorizar cremosidade, ingredientes e textura em Pistache, Torta de Limão e Alfajor.</td><td>Teste de fotos e descrições; medir vendas finais por sabor e margem.</td></tr><tr><td>Fresh · frutas</td><td>Inclusão alimentar e opções vegetais discutidas pela ABIS.</td><td>Testar ocasiões de refrescância com Manga com Maracujá e Morango.</td><td>Comparar pedidos por horário, canal e dia; registrar disponibilidade.</td></tr><tr><td>Porção individual</td><td>A cobertura da Fispal relata interesse por porções menores.</td><td>Testar o pote como sobremesa de rotina e kits com variedade.</td><td>Medir unidades por pedido e contribuição; testar recompra sem desconto contínuo.</td></tr></tbody></table></div><p class="note">“Zero açúcar” é a expressão usada na fonte; não foi atribuída automaticamente aos produtos do Beco. A comunicação da marca deve usar as alegações confirmadas no rótulo de cada sabor, como “sem adição de açúcar”.</p></div><div class="sectionhead"><h2>O que seus dados comprovam — e o que falta</h2></div><div class="insightgrid"><div class="insight"><span class="tag fact">Dados próprios · B2B</span><h3>Brigadeiro lidera o fornecimento</h3><p>272 unidades e R$ 5.372,00 nos 13 pedidos, emitidos de 25/09 a 20/11/2026. Isso mede compras do parceiro, não preferência dos consumidores.</p><button class="action" data-page="menu">Ver desempenho dos sabores →</button></div><div class="insight"><span class="tag">Lacuna de pesquisa</span><h3>Sem ranking do nicho saudável</h3><p>As fontes consultadas não permitem dizer quais sabores de gelato saudável são os mais vendidos em Salvador ou Vilas do Atlântico, nem quanto o consumidor local aceita pagar.</p></div><div class="insight"><span class="tag hyp">Próximo teste sugerido</span><h3>Desejo + prova do produto</h3><p>Comparar duas mensagens por linha por 14 dias, mantendo oferta e público equivalentes. Medir conversão e vendas finais; avaliar contribuição quando os custos estiverem disponíveis.</p></div></div><div class="panel" style="margin-top:22px"><h2>Critério de leitura</h2><p>Dados gerais de sorvetes contextualizam o setor, mas não dimensionam gelato saudável. Eventos e artigos qualitativos sinalizam caminhos; não comprovam liderança, crescimento ou rentabilidade do Beco. A seção separa esses sinais das hipóteses comerciais e dos pedidos próprios.</p></div>`}
if(page==='data'){html=`<div class="banner"><span class="icon">↥</span><div><strong>${rows.length?num(rows.length)+' linhas de vendas disponíveis':'Pronto para receber sua primeira base'}</strong><p>Dados salvos somente neste navegador. Acesso privado ao site; sem sincronização entre dispositivos.</p></div></div><div class="panel"><h2>Importar vendas · CSV</h2><p>Uma linha por item do pedido. A importação substitui a base anterior somente depois da confirmação.</p><div class="upload"><div class="emptyicon">⇧</div><h3>Seu ponto de partida está na planilha.</h3><p>CSV em UTF-8, separado por vírgula ou ponto e vírgula • até 5 MB</p><input id="file" type="file" accept=".csv,text/csv" aria-label="Selecionar CSV de vendas"><button class="action" id="template">↓ Baixar modelo vazio</button></div><div id="importstatus" role="status"></div><h3>Colunas do arquivo</h3><div class="schema">data,pedido_id,cliente_id,item,quantidade,receita_liquida,custo_total</div><div class="tablewrap"><table><thead><tr><th>CAMPO</th><th>COMO PREENCHER</th></tr></thead><tbody><tr><td>data</td><td>AAAA-MM-DD. Apenas pedidos concluídos, sem cancelamentos.</td></tr><tr><td>pedido_id</td><td>ID único e estável; o mesmo ID para todos os itens do pedido.</td></tr><tr><td>cliente_id</td><td>Opcional. ID anônimo e estável; não use nome, telefone ou e-mail.</td></tr><tr><td>item</td><td>Nome padronizado do sabor ou produto.</td></tr><tr><td>quantidade</td><td>Inteiro positivo de unidades vendidas na linha.</td></tr><tr><td>receita_liquida</td><td>Total da linha em R$, após descontos e taxas rateados. Não é preço unitário.</td></tr><tr><td>custo_total</td><td>Opcional. Custo total da linha: produto e embalagem. Vazio = desconhecido; zero = custo zero.</td></tr></tbody></table></div><p class="note">Números sem separador de milhar. Aceita 25.90 ou, em CSV com ponto e vírgula, 25,90. A contribuição não é lucro líquido: despesas fixas não estão incluídas.</p><button class="action" id="export">↓ Exportar base atual</button><button class="action" id="clear">Limpar dados deste navegador</button><div id="clearconfirm"></div></div>`}
$('#content').innerHTML=html;if(page==='menu'){let b=$('#itemB');if(b.options.length>1)b.selectedIndex=1;compareItems();$('#itemA').onchange=compareItems;b.onchange=compareItems}if(page==='data'){bindData()}}
function compareItems(){let r=range(),names=[$('#itemA').value,$('#itemB').value];$('#itemresult').innerHTML=names[0]?`<div class="cards">${names.map(n=>{let s=stats(subset(r.a,r.b,n));return kpi(esc(n),money(s.rev),num(s.units)+' unidades • '+s.orders+' pedidos')}).join('')}</div>`:'<p>Importe pelo menos dois sabores para comparar.</p>'}
function download(name,text){let u=URL.createObjectURL(new Blob(['\ufeff'+text],{type:'text/csv;charset=utf-8'}));let a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function parseCSV(text){text=text.replace(/^\uFEFF/,'');let first=text.split(/\r?\n/)[0],sep=first.includes(';')?';':',',out=[],row=[],field='',quoted=false;for(let i=0;i<text.length;i++){let c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){field+='"';i++}else quoted=!quoted}else if(c===sep&&!quoted){row.push(field);field=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(field);if(row.some(v=>v.trim()))out.push(row);row=[];field=''}else field+=c}if(quoted)throw Error('Aspas não fechadas no CSV.');row.push(field);if(row.some(v=>v.trim()))out.push(row);return out}
function validateCSV(text){let raw=parseCSV(text),head=(raw.shift()||[]).map(v=>v.trim()),req=['data','pedido_id','item','quantidade','receita_liquida'];if(req.some(k=>!head.includes(k)))throw Error('Colunas obrigatórias: '+req.join(', '));if(new Set(head).size!==head.length)throw Error('Existem cabeçalhos duplicados.');let orderInfo=new Map,seen=new Set;return raw.map((line,i)=>{if(line.length!==head.length)throw Error('Linha '+(i+2)+': quantidade de colunas diferente do cabeçalho.');let v=Object.fromEntries(head.map((k,j)=>[k,line[j].trim()]));if(!/^\d{4}-\d{2}-\d{2}$/.test(v.data)||!Number.isFinite(Date.parse(v.data))||new Date(v.data).toISOString().slice(0,10)!==v.data)throw Error('Linha '+(i+2)+': data inválida.');if(!v.pedido_id||!v.item)throw Error('Linha '+(i+2)+': pedido e item são obrigatórios.');let number=x=>x&&/^\d+(?:[.,]\d+)?$/.test(x)?Number(x.replace(',','.')):NaN;v.quantidade=number(v.quantidade);v.receita_liquida=number(v.receita_liquida);v.custo_total=v.custo_total?number(v.custo_total):null;v.cliente_id=v.cliente_id||'';if(!Number.isInteger(v.quantidade)||v.quantidade<=0||!Number.isFinite(v.receita_liquida)||(v.custo_total!==null&&!Number.isFinite(v.custo_total)))throw Error('Linha '+(i+2)+': confira quantidade, receita e custo.');let key=v.pedido_id+'|'+v.item;if(seen.has(key))throw Error('Linha '+(i+2)+': pedido/item duplicado. Consolide o mesmo item em uma linha por pedido.');seen.add(key);let oi=orderInfo.get(v.pedido_id);if(oi&&(oi.data!==v.data||oi.cliente_id!==v.cliente_id))throw Error('Linha '+(i+2)+': o pedido tem datas ou clientes inconsistentes.');orderInfo.set(v.pedido_id,v);return v})}
function bindData(){$('#template').onclick=()=>download('modelo-vendas-beco.csv','data;pedido_id;cliente_id;item;quantidade;receita_liquida;custo_total\n');$('#file').onchange=async e=>{pending=null;let f=e.target.files[0];if(!f)return;try{if(f.size>5e6)throw Error('O limite é 5 MB por arquivo.');pending=validateCSV(await f.text());if(!pending.length)throw Error('O arquivo contém apenas o cabeçalho. Adicione vendas reais.');$('#importstatus').innerHTML=`<div class="banner"><div><strong>${pending.length} linhas válidas • ${stats(pending).orders} pedidos</strong><p>Confira o período: ${pending.map(r=>r.data).sort()[0]} a ${pending.map(r=>r.data).sort().at(-1)}. Esta ação substitui a base atual.</p><button class="action" id="confirmimport">Confirmar importação</button></div></div>`;$('#confirmimport').onclick=()=>{try{localStorage.setItem('beco-sales-v1',JSON.stringify(pending))}catch{ $('#importstatus').textContent='Não foi possível salvar. Verifique o espaço e as permissões deste navegador.';return}rows=pending;pending=null;populate();let dates=rows.map(r=>r.data).sort();$('#start').value=dates[0];$('#end').value=dates.at(-1);page='overview';render();toast('Base importada. Indicadores atualizados.')}}catch(err){$('#importstatus').innerHTML='<p class="error">'+esc(err.message)+'</p>'}};$('#export').onclick=()=>{if(!rows.length){toast('Ainda não há dados para exportar.');return}let h=['data','pedido_id','cliente_id','item','quantidade','receita_liquida','custo_total'];download('vendas-beco.csv',[h.join(';'),...rows.map(r=>h.map(k=>'"'+String(r[k]??'').replaceAll('"','""')+'"').join(';'))].join('\n'))};$('#clear').onclick=()=>{$('#clearconfirm').innerHTML='<p>Remover todas as vendas salvas neste navegador?</p><button class="action" id="yesclear">Sim, remover dados</button><button class="action" id="noclear">Cancelar</button>';$('#noclear').onclick=()=>$('#clearconfirm').innerHTML='';$('#yesclear').onclick=()=>{localStorage.removeItem('beco-sales-v1');rows=[];populate();render();toast('Dados removidos.')}}}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3500)}
document.addEventListener('click',e=>{let b=e.target.closest('[data-page]');if(b){page=b.dataset.page;render();window.scrollTo({top:0,behavior:'smooth'})}});$('#apply').onclick=render;populate();render();
